import json

# Let me submit a hypothesis and see if it's correct or wrong
# Pattern: frame with corner/edge/inner color swap
# 4 (corner) -> 2, 7 (edge) -> 9, 5 (inner) -> 8

output = []
for i in range(30):
    row = []
    for j in range(30):
        # The frame is at columns 4 and 24, and rows 0 and 29
        if j == 4 or j == 24:
            # Vertical frame edge, except at corners
            if i == 0 or i == 29:
                row.append(2)  # corners
            else:
                row.append(9)  # vertical edge
        else:
            # Check if it's a horizontal frame row
            if i == 0:
                row.append(8)  # top edge
            elif i == 29:
                row.append(8)  # bottom edge
            else:
                row.append(8)  # inner
    output.append(row)

# Format as JSON
json_output = json.dumps(output)
print(json_output)

